    )
    side_extent = 0.5 * (
        enemy.length * abs(sin(angle)) + enemy.width * abs(cos(angle))
    )

    in_front_zone = dist <= me.length * 0.5 + 0.35 + forward_extent + 0.08
    overlaps_width = dist * abs(sin(angle)) <= 0.45 + side_extent
    if in_front_zone and overlaps_width and abs(degrees(angle)) < 55:
        return flip("front")
    return None

