    dist = distance_to(enemy.x, enemy.y)
    mem = me.memory

    escape = mem.get("escape", 0)
    if escape > 0:
        mem["escape"] = escape - 1
        return (-1, -1)

    stuck = mem.get("stuck", 0)
    if dist < 2.0 and abs(me.speed) < 0.35:
        stuck = stuck + 1
    else:
        stuck = max(0, stuck - 2)

    if stuck > 30:
        mem["stuck"] = 0
        mem["escape"] = 8
        return (-1, -1)

    mem["stuck"] = stuck

    if hypot(me.x, me.y) > 5.5:
        angle = bearing_to(0, 0)
    else:
        angle = bearing_to(enemy.x, enemy.y)

    turn = max(-1, min(1, angle / 38))
    forward = 1
    if abs(angle) > 65:
        forward = 0.25
    elif abs(angle) > 35:
        forward = 0.65

    left = forward + turn
    right = forward - turn
    scale = max(1, abs(left), abs(right))
    return (left / scale, right / scale)


